"use client";

import { useId, useState } from "react";
import { RiFireFill, RiRunFill, RiUserSmileLine } from "@remixicon/react";

import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Activity Rings Card: Apple Watch-style concentric move / exercise / stand
 * rings with matching stat tiles underneath.
 */

export type ActivityDay = {
  move: number;
  moveGoal: number;
  exercise: number;
  exerciseGoal: number;
  stand: number;
  standGoal: number;
};

const DEFAULT_DAY: ActivityDay = {
  move: 1592,
  moveGoal: 1800,
  exercise: 105,
  exerciseGoal: 120,
  stand: 10,
  standGoal: 12,
};

type RingDef = {
  key: "move" | "exercise" | "stand";
  label: string;
  color: string;
  track: string;
  radius: number;
  progress: number;
  valueLabel: string;
  unit: string;
  icon: typeof RiFireFill;
};

function ringPath(cx: number, cy: number, r: number, progress: number) {
  const clamped = Math.max(0, Math.min(1, progress));
  const sweep = clamped * 359.9;
  const start = (-90 * Math.PI) / 180;
  const end = ((-90 + sweep) * Math.PI) / 180;
  const x1 = cx + r * Math.cos(start);
  const y1 = cy + r * Math.sin(start);
  const x2 = cx + r * Math.cos(end);
  const y2 = cy + r * Math.sin(end);
  const large = sweep > 180 ? 1 : 0;
  return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`;
}

export function ActivityRingsCard({
  day = DEFAULT_DAY,
  className,
}: {
  day?: ActivityDay;
  className?: string;
} = {}) {
  const [focus, setFocus] = useState<RingDef["key"] | null>(null);
  const filterId = useId();
  const move = useCountUp(day.move);

  const rings: RingDef[] = [
    {
      key: "move",
      label: "活动",
      color: "var(--color-chart-3-active)",
      track: "color-mix(in srgb, var(--color-chart-3) 22%, transparent)",
      radius: 54,
      progress: day.move / day.moveGoal,
      valueLabel: `${move.toLocaleString("en-US")} kcal`,
      unit: `目标 ${day.moveGoal.toLocaleString("en-US")}`,
      icon: RiFireFill,
    },
    {
      key: "exercise",
      label: "锻炼",
      color: "var(--color-chart-7-active)",
      track: "color-mix(in srgb, var(--color-chart-7) 22%, transparent)",
      radius: 40,
      progress: day.exercise / day.exerciseGoal,
      valueLabel: `${Math.floor(day.exercise / 60)}h ${day.exercise % 60}m`,
      unit: `目标 ${day.exerciseGoal}m`,
      icon: RiRunFill,
    },
    {
      key: "stand",
      label: "站立",
      color: "var(--color-chart-6-active)",
      track: "color-mix(in srgb, var(--color-chart-6) 22%, transparent)",
      radius: 26,
      progress: day.stand / day.standGoal,
      valueLabel: `${day.stand} 小时`,
      unit: `目标 ${day.standGoal}`,
      icon: RiUserSmileLine,
    },
  ];

  return (
    <section
      className={cx(
        "flex min-w-0 flex-1 flex-col gap-5 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex flex-col gap-0.5">
        <p className="text-body-medium text-text-secondary">活动圆环</p>
        <p className="text-title-2-medium text-text-primary">今日目标</p>
      </div>

      <div className="flex justify-center py-1">
        <svg viewBox="0 0 140 140" className="size-[180px]" role="img" aria-label="Activity rings">
          <defs>
            <filter id={filterId} x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy="1" stdDeviation="1.5" floodOpacity="0.18" />
            </filter>
          </defs>
          {rings.map((ring) => {
            const active = focus === null || focus === ring.key;
            return (
              <g
                key={ring.key}
                opacity={active ? 1 : 0.22}
                className="transition-opacity duration-200"
                onMouseEnter={() => setFocus(ring.key)}
                onMouseLeave={() => setFocus(null)}
              >
                <circle
                  cx="70"
                  cy="70"
                  r={ring.radius}
                  fill="none"
                  stroke={ring.track}
                  strokeWidth="11"
                />
                <path
                  d={ringPath(70, 70, ring.radius, ring.progress)}
                  fill="none"
                  stroke={ring.color}
                  strokeWidth="11"
                  strokeLinecap="round"
                  filter={`url(#${filterId})`}
                />
              </g>
            );
          })}
        </svg>
      </div>

      <div className="grid grid-cols-3 gap-2">
        {rings.map((ring) => {
          const Icon = ring.icon;
          const active = focus === null || focus === ring.key;
          return (
            <button
              key={ring.key}
              type="button"
              className={cx(
                "flex flex-col gap-1 rounded-2lg bg-background-inner-default px-2.5 py-2 text-start shadow-card outline-none transition-opacity duration-200",
                !active && "opacity-40",
              )}
              onMouseEnter={() => setFocus(ring.key)}
              onMouseLeave={() => setFocus(null)}
            >
              <div className="flex items-center gap-1.5">
                <Icon className="size-3.5 shrink-0" style={{ color: ring.color }} aria-hidden />
                <span className="truncate text-caption-1-medium text-text-tertiary">{ring.label}</span>
              </div>
              <p className="text-body-medium text-text-primary tabular-nums">{ring.valueLabel}</p>
              <p className="text-caption-1-medium text-text-tertiary">{ring.unit}</p>
            </button>
          );
        })}
      </div>
    </section>
  );
}

"use client";

import { useId, useMemo, useState } from "react";
import { Area, AreaChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { Chip } from "@/components/ui/badges/chip";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "@/components/ui/segmented-control/segmented-control";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Area Chart Card: stacked Product / Services / Other revenue with soft gradients.
 * Hover swaps the headline to that month’s stack total; footer tiles hold series sums.
 */

type Period = "weekly" | "monthly" | "yearly";

export type AreaChartPoint = {
  label: string;
  product: number;
  services: number;
  other: number;
};

const SERIES = [
  { key: "product" as const, label: "Product", color: "var(--color-chart-2)", active: "var(--color-chart-2-active)", swatch: "bg-chart-2-active" },
  { key: "services" as const, label: "Services", color: "var(--color-chart-6)", active: "var(--color-chart-6-active)", swatch: "bg-chart-6-active" },
  { key: "other" as const, label: "Other", color: "var(--color-chart-5)", active: "var(--color-chart-5-active)", swatch: "bg-chart-5-active" },
];

const PERIOD_META: Record<Period, { total: number; delta: number }> = {
  weekly: { total: 28640, delta: 7.6 },
  monthly: { total: 128450, delta: 14.8 },
  yearly: { total: 1541400, delta: 18.2 },
};

function scaleYear(factor: number): AreaChartPoint[] {
  const base: AreaChartPoint[] = [
    { label: "1月", product: 6200, services: 3100, other: 1400 },
    { label: "2月", product: 6800, services: 3400, other: 1500 },
    { label: "3月", product: 7100, services: 3600, other: 1600 },
    { label: "4月", product: 7400, services: 3800, other: 1700 },
    { label: "5月", product: 7900, services: 4100, other: 1800 },
    { label: "6月", product: 8200, services: 4300, other: 1900 },
    { label: "7月", product: 8600, services: 4500, other: 2000 },
    { label: "8月", product: 8400, services: 4400, other: 1950 },
    { label: "9月", product: 8800, services: 4700, other: 2100 },
    { label: "10月", product: 9200, services: 4900, other: 2200 },
    { label: "11月", product: 8700, services: 4600, other: 2050 },
    { label: "12月", product: 9100, services: 4800, other: 2150 },
  ];
  return base.map((row) => ({
    label: row.label,
    product: Math.round(row.product * factor),
    services: Math.round(row.services * factor),
    other: Math.round(row.other * factor),
  }));
}

/** Base year totals ~169,950; scale so monthly headline lands on $128,450. */
const MONTHLY_FACTOR = 128450 / 169950;

const PERIOD_DATA: Record<Period, AreaChartPoint[]> = {
  weekly: scaleYear(MONTHLY_FACTOR * 0.22),
  monthly: scaleYear(MONTHLY_FACTOR),
  yearly: scaleYear(MONTHLY_FACTOR * 12),
};

const formatMoney = (value: number) =>
  value.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 0 });

const formatK = (value: number) =>
  value >= 1000 ? `$${Math.round(value / 1000)}k` : `$${value}`;

function formatDelta(delta: number) {
  const rounded = Math.round(delta * 10) / 10;
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : rounded < 0 ? ("rose" as const) : ("neutral" as const),
  };
}

function rowTotal(point: AreaChartPoint) {
  return point.product + point.services + point.other;
}

export function AreaChartCard({
  className,
  title = "Revenue",
}: {
  className?: string;
  /** Headline label when no month is hovered. */
  title?: string;
} = {}) {
  const [period, setPeriod] = useState<Period>("monthly");
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const gradientId = useId();

  const data = PERIOD_DATA[period];
  const meta = PERIOD_META[period];
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? rowTotal(point) : meta.total;
  const label = point ? point.label : title;
  const delta = formatDelta(meta.delta);
  const display = useCountUp(Math.round(headlineValue));

  const seriesTotals = useMemo(() => {
    return SERIES.map((series) => ({
      ...series,
      total: data.reduce((sum, row) => sum + row[series.key], 0),
    }));
  }, [data]);

  const yMax = useMemo(() => Math.max(...data.map(rowTotal)), [data]);

  return (
    <section
      className={cx(
        "flex flex-col gap-4 rounded-2xl bg-background-secondary-default p-4",
        className,
      )}
    >
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={`${period}-${activeIndex ?? "total"}`}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              ${formatMoney(display)}
            </p>
            <Chip variant="bold" color={delta.color}>
              {delta.label}
            </Chip>
          </div>
        </div>

        <SegmentedControl
          aria-label="周期"
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const next = [...(keys as Set<string>)][0] as Period | undefined;
            if (next) {
              setPeriod(next);
              setActiveIndex(null);
            }
          }}
          className="shrink-0 self-start"
        >
          <SegmentedControlItem id="weekly">每周</SegmentedControlItem>
          <SegmentedControlItem id="monthly">每月</SegmentedControlItem>
          <SegmentedControlItem id="yearly">每年</SegmentedControlItem>
        </SegmentedControl>
      </div>

      <div className="h-[220px] w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart
            data={data}
            margin={{ top: 8, right: 6, bottom: 0, left: 0 }}
            onMouseMove={(state) => {
              const index = Number(state?.activeTooltipIndex);
              if (state?.isTooltipActive && Number.isFinite(index)) setActiveIndex(index);
            }}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <defs>
              {SERIES.map((series) => (
                <linearGradient
                  key={series.key}
                  id={`${gradientId}-${series.key}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop offset="0%" stopColor={series.color} stopOpacity={0.45} />
                  <stop offset="100%" stopColor={series.color} stopOpacity={0.05} />
                </linearGradient>
              ))}
            </defs>
            <YAxis
              width={44}
              domain={[0, yMax * 1.1]}
              tickCount={4}
              tickFormatter={formatK}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <XAxis
              dataKey="label"
              tickLine={false}
              axisLine={false}
              tickMargin={12}
              interval="preserveStartEnd"
              tick={{ fontSize: 13, fill: "var(--color-text-tertiary)" }}
            />
            <Tooltip
              content={() => null}
              cursor={{ stroke: "var(--color-chart-cursor)", strokeWidth: 1, strokeDasharray: "4 4" }}
            />
            {SERIES.map((series) => (
              <Area
                key={series.key}
                type="monotone"
                dataKey={series.key}
                stackId="revenue"
                stroke={series.active}
                strokeWidth={1.5}
                fill={`url(#${gradientId}-${series.key})`}
                isAnimationActive
                animationDuration={450}
              />
            ))}
          </AreaChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-3 gap-2">
        {seriesTotals.map((series) => (
          <div
            key={series.key}
            className="flex flex-col gap-0.5 rounded-xl bg-background-tertiary-default px-3 py-2.5"
          >
            <div className="flex items-center gap-1.5 text-body-2-medium text-text-secondary">
              <span className={cx("size-2 rounded-full", series.swatch)} aria-hidden />
              <span>{series.label}</span>
            </div>
            <p className="text-title-2-medium text-text-primary tabular-nums">
              ${formatMoney(series.total)}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  RiAndroidLine,
  RiAppleLine,
  RiChromeLine,
  RiComputerLine,
  RiEdgeLine,
  RiFirefoxLine,
  RiSafariLine,
  RiSmartphoneLine,
  RiTabletLine,
  RiWindowsLine,
} from "@remixicon/react";

import { cx } from "@/lib/utils";

export type BarListItem = {
  label: string;
  /** Absolute count — share is derived against the tab total. */
  value: number;
  icon?: ReactNode;
};

export type BarListTab = {
  id: string;
  label: string;
  items: BarListItem[];
};

export type BarListCardProps = {
  /** Tabbed breakdowns. Defaults to Devices / Browsers / OS / Screen sizes. */
  tabs?: BarListTab[];
  /** Single-list mode (no tabs). Ignored when `tabs` is set. */
  items?: BarListItem[];
  /** Heading when using a single list. */
  title?: string;
  /** Right-side metric caption (e.g. 访客). */
  metricLabel?: string;
  defaultTab?: string;
  onTabChange?: (id: string) => void;
  /** Cap visible rows; remainder collapses behind a show-more control. */
  limit?: number;
  /** Grey bars instead of the soft accent fill. */
  mono?: boolean;
  className?: string;
};

function DesktopIcon() {
  return <RiComputerLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden />;
}
function PhoneIcon() {
  return <RiSmartphoneLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden />;
}
function TabletIcon() {
  return <RiTabletLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden />;
}

const DEFAULT_TABS: BarListTab[] = [
  {
    id: "devices",
    label: "设备",
    items: [
      { label: "桌面", value: 6100, icon: <DesktopIcon /> },
      { label: "手机", value: 3100, icon: <PhoneIcon /> },
      { label: "平板电脑", value: 800, icon: <TabletIcon /> },
    ],
  },
  {
    id: "browsers",
    label: "浏览器",
    items: [
      { label: "Chrome", value: 4200, icon: <RiChromeLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
      { label: "Safari", value: 2800, icon: <RiSafariLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
      { label: "Edge", value: 1900, icon: <RiEdgeLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
      { label: "Firefox", value: 1100, icon: <RiFirefoxLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
    ],
  },
  {
    id: "os",
    label: "操作系统",
    items: [
      { label: "Windows", value: 4500, icon: <RiWindowsLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
      { label: "macOS", value: 3200, icon: <RiAppleLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
      { label: "iOS", value: 1500, icon: <RiSmartphoneLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
      { label: "Android", value: 800, icon: <RiAndroidLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> },
    ],
  },
  {
    id: "screens",
    label: "屏幕尺寸",
    items: [
      { label: "1920×1080", value: 3800 },
      { label: "1366×768", value: 2400 },
      { label: "390×844", value: 2100 },
      { label: "Other", value: 1700 },
    ],
  },
];

/**
 * Bar List Card — ranked share rows with optional tabbed breakdowns.
 * Tabbed analytics breakdown: Devices / Browsers / OS / Screen sizes.
 */
export function BarListCard({
  tabs,
  items,
  title,
  metricLabel = "访客",
  defaultTab,
  onTabChange,
  limit,
  mono = false,
  className,
}: BarListCardProps = {}) {
  const resolvedTabs = tabs ?? (items
    ? [{ id: "list", label: title ?? "列表", items }]
    : DEFAULT_TABS);
  const single = !tabs && Boolean(items);
  const initial =
    defaultTab && resolvedTabs.some((t) => t.id === defaultTab)
      ? defaultTab
      : resolvedTabs[0]?.id;
  const [tabId, setTabId] = useState(initial);
  const [expanded, setExpanded] = useState(false);

  const active = useMemo(
    () => resolvedTabs.find((t) => t.id === tabId) ?? resolvedTabs[0],
    [resolvedTabs, tabId],
  );
  const rows = active?.items ?? [];
  const total = rows.reduce((sum, row) => sum + row.value, 0) || 1;
  const visible =
    limit && !expanded ? rows.slice(0, limit) : rows;
  const hidden = limit ? Math.max(0, rows.length - limit) : 0;

  return (
    <section
      className={cx(
        "flex min-w-0 flex-1 flex-col gap-3 rounded-2xl bg-background-secondary-default px-4 pt-3 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-end justify-between gap-3 border-b border-separator-border">
        {single ? (
          <p className="pb-2.5 text-body-medium text-text-primary">{title}</p>
        ) : (
          <div
            role="tablist"
            aria-label="分类"
            className="flex min-w-0 flex-1 items-center gap-4 overflow-x-auto [scrollbar-width:none]"
          >
            {resolvedTabs.map((tab) => {
              const selected = tab.id === active?.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  role="tab"
                  aria-selected={selected}
                  onClick={() => {
                    setTabId(tab.id);
                    setExpanded(false);
                    onTabChange?.(tab.id);
                  }}
                  className={cx(
                    "relative shrink-0 pb-2.5 text-body-medium outline-none transition-colors",
                    "focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2",
                    selected
                      ? "text-status-orange-text"
                      : "text-text-secondary hover:text-text-primary",
                  )}
                >
                  {tab.label}
                  {selected ? (
                    <span
                      aria-hidden
                      className="absolute inset-x-0 bottom-0 h-0.5 rounded-full bg-status-orange-text"
                    />
                  ) : null}
                </button>
              );
            })}
          </div>
        )}
        <p className="shrink-0 pb-2.5 text-caption-1-medium text-text-tertiary">
          {metricLabel}
        </p>
      </div>

      <ul className="flex flex-col gap-1.5">
        {visible.map((row) => {
          const share = Math.round((row.value / total) * 100);
          return (
            <li key={row.label} className="relative">
              <div
                aria-hidden
                className={cx(
                  "absolute inset-y-0 start-0 rounded-lg transition-[width] duration-500 ease-out",
                  mono ? "bg-background-tertiary-default" : "bg-accent-100",
                )}
                style={{ width: `${share}%` }}
              />
              <div className="relative flex items-center gap-2 px-2.5 py-2">
                {row.icon ? (
                  <span className="flex size-4 shrink-0 items-center justify-center">
                    {row.icon}
                  </span>
                ) : null}
                <span className="min-w-0 flex-1 truncate text-body-medium text-text-primary">
                  {row.label}
                </span>
                <span className="shrink-0 text-body-medium text-text-primary tabular-nums">
                  {share}%
                </span>
              </div>
            </li>
          );
        })}
      </ul>

      {hidden > 0 && !expanded ? (
        <button
          type="button"
          onClick={() => setExpanded(true)}
          className="self-start rounded-full bg-background-tertiary-default px-2.5 py-1 text-caption-1-medium text-text-secondary hover:bg-background-tertiary-hover"
        >
          显示其余 {hidden} 项
        </button>
      ) : null}
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  Cell,
  ComposedChart,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import { Chip } from "@/components/ui/badges/chip";
import { Button } from "@/components/ui/buttons/button";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Combo Chart Card: sessions bars (lime) and conversion line (blue) on dual axes.
 * Hover darkens the active bar, pulses the line dot, and swaps the headline.
 */

export type ComboChartPoint = {
  label: string;
  sessions: number;
  conversion: number;
};

/** Twelve months that total 83,200 sessions at a 3.7% average conversion. */
export const COMBO_DATA: ComboChartPoint[] = [
  { label: "1月", sessions: 5800, conversion: 2.8 },
  { label: "2月", sessions: 6200, conversion: 3.0 },
  { label: "3月", sessions: 6500, conversion: 3.2 },
  { label: "4月", sessions: 6700, conversion: 3.1 },
  { label: "5月", sessions: 7000, conversion: 3.4 },
  { label: "6月", sessions: 7200, conversion: 3.6 },
  { label: "7月", sessions: 7600, conversion: 3.9 },
  { label: "8月", sessions: 7400, conversion: 3.7 },
  { label: "9月", sessions: 7800, conversion: 4.0 },
  { label: "10月", sessions: 7500, conversion: 4.1 },
  { label: "11月", sessions: 7100, conversion: 3.8 },
  { label: "12月", sessions: 6400, conversion: 3.5 },
];

const CONVERSION_AVG = 3.7;

const formatCount = (value: number) => value.toLocaleString("en-US");
const formatK = (value: number) =>
  value >= 1000 ? `${Math.round(value / 1000)}k` : `${value}`;
const formatPct = (value: number) => `${value}%`;

function ActiveDot({ cx: x, cy: y }: { cx?: number; cy?: number }) {
  if (x === undefined || y === undefined) return null;
  return (
    <g>
      <circle cx={x} cy={y} r={10} fill="var(--color-chart-6-active)" opacity={0.22}>
        <animate attributeName="r" values="7;12;7" dur="1.25s" repeatCount="indefinite" />
        <animate attributeName="opacity" values="0.32;0.08;0.32" dur="1.25s" repeatCount="indefinite" />
      </circle>
      <circle
        cx={x}
        cy={y}
        r={4}
        fill="var(--color-chart-6-active)"
        stroke="var(--color-background-secondary-default)"
        strokeWidth={2}
      />
    </g>
  );
}

export function ComboChartCard({
  data = COMBO_DATA,
  className,
  delta = 9.4,
  conversionRate = CONVERSION_AVG,
}: {
  data?: ComboChartPoint[];
  className?: string;
  /** Headline delta percentage. */
  delta?: number;
  /** Shown in the title and conversion tile. */
  conversionRate?: number;
} = {}) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const sessionsTotal = useMemo(
    () => data.reduce((sum, point) => sum + point.sessions, 0),
    [data],
  );
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? point.sessions : sessionsTotal;
  const title = point
    ? `${point.label} · Conversion ${formatPct(point.conversion)}`
    : `Sessions · Conversion ${formatPct(conversionRate)}`;
  const deltaLabel = `${delta > 0 ? "+" : ""}${delta}%`;
  const display = useCountUp(Math.round(headlineValue));

  const sessionsMax = Math.max(...data.map((d) => d.sessions));
  const conversionMax = Math.max(...data.map((d) => d.conversion));

  return (
    <section
      className={cx(
        "flex flex-col gap-4 rounded-2xl bg-background-secondary-default p-4",
        className,
      )}
    >
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{title}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={activeIndex ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {formatCount(display)}
            </p>
            <Chip variant="bold" color={delta > 0 ? "lime" : delta < 0 ? "rose" : "neutral"}>
              {deltaLabel}
            </Chip>
          </div>
        </div>

        <Button variant="secondary" size="xs" className="shrink-0 self-start" type="button">
          今年
        </Button>
      </div>

      <div className="h-[220px] w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={data}
            margin={{ top: 8, right: 8, bottom: 0, left: 0 }}
            barCategoryGap="28%"
            onMouseMove={(state) => {
              const index = Number(state?.activeTooltipIndex);
              if (state?.isTooltipActive && Number.isFinite(index)) setActiveIndex(index);
            }}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <YAxis
              yAxisId="sessions"
              width={40}
              domain={[0, sessionsMax * 1.15]}
              tickCount={4}
              tickFormatter={formatK}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <YAxis
              yAxisId="conversion"
              orientation="right"
              width={36}
              domain={[0, conversionMax * 1.25]}
              tickCount={4}
              tickFormatter={formatPct}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <XAxis
              dataKey="label"
              tickLine={false}
              axisLine={false}
              tickMargin={12}
              interval="preserveStartEnd"
              tick={{ fontSize: 13, fill: "var(--color-text-tertiary)" }}
            />
            <Tooltip content={() => null} cursor={{ fill: "var(--color-chart-track)", opacity: 0.45 }} />
            <Bar
              yAxisId="sessions"
              dataKey="sessions"
              radius={[6, 6, 6, 6]}
              isAnimationActive
              animationDuration={450}
            >
              {data.map((entry, index) => {
                const dimmed = activeIndex !== null && activeIndex !== index;
                const active = activeIndex === index;
                return (
                  <Cell
                    key={entry.label}
                    fill={active ? "var(--color-chart-2-active)" : "var(--color-chart-2)"}
                    fillOpacity={dimmed ? 0.35 : 1}
                  />
                );
              })}
            </Bar>
            <Line
              yAxisId="conversion"
              type="monotone"
              dataKey="conversion"
              stroke="var(--color-chart-6-active)"
              strokeWidth={2.5}
              dot={false}
              activeDot={<ActiveDot />}
              isAnimationActive
              animationDuration={450}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <div className="flex flex-col gap-0.5 rounded-xl bg-background-tertiary-default px-3 py-2.5">
          <div className="flex items-center gap-1.5 text-body-2-medium text-text-secondary">
            <span className="size-2 rounded-full bg-chart-2-active" aria-hidden />
            <span>Sessions 总计</span>
          </div>
          <p className="text-title-2-medium text-text-primary tabular-nums">
            {formatCount(sessionsTotal)}
          </p>
        </div>
        <div className="flex flex-col gap-0.5 rounded-xl bg-background-tertiary-default px-3 py-2.5">
          <div className="flex items-center gap-1.5 text-body-2-medium text-text-secondary">
            <span className="size-2 rounded-full bg-chart-6-active" aria-hidden />
            <span>Conversion average</span>
          </div>
          <p className="text-title-2-medium text-text-primary tabular-nums">
            {formatPct(conversionRate)}
          </p>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";
import { Chip } from "@/components/ui/badges/chip";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "@/components/ui/segmented-control/segmented-control";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

type Range = "weekly" | "monthly" | "yearly";

const STATS = [
  { value: "9B", label: "累计 Token" },
  { value: "562.7M", label: "峰值 Token" },
  { value: "12h 54m", label: "最长任务时长" },
  { value: "62 days", label: "最长连续活跃天数" },
] as const;

function buildHeatmap(seed: number) {
  // 53 weeks × 7 days — GitHub-style contribution grid
  return Array.from({ length: 53 * 7 }, (_, i) => {
    const n = ((i * 17 + seed * 13) % 97) / 97;
    if (n < 0.42) return 0;
    if (n < 0.62) return 1;
    if (n < 0.78) return 2;
    if (n < 0.9) return 3;
    return 4;
  });
}

const LEVEL_CLASS = [
  "bg-background-tertiary-default",
  "bg-heatmap-1",
  "bg-heatmap-2",
  "bg-heatmap-3",
  "bg-heatmap-4",
] as const;

const MONTHS = ["1月", "2月", "3月", "4月", "5月", "6月", "7月", "8月", "9月", "10月", "11月", "12月"];

/**
 * Contributions Card — year contribution count, KPI tiles, and a purple
 * GitHub-style activity heatmap with a period switcher.
 */
export function ContributionsCard({ className }: { className?: string }) {
  const [range, setRange] = useState<Range>("weekly");
  const cells = useMemo(
    () => buildHeatmap(range === "weekly" ? 1 : range === "monthly" ? 2 : 3),
    [range],
  );
  const total = useCountUp(958);

  return (
    <section
      className={cx(
        "flex w-full min-w-0 flex-col gap-4 rounded-2xl bg-background-secondary-default p-4",
        className,
      )}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="text-body-medium text-text-secondary">今年的贡献</p>
          <div className="mt-0.5 flex items-center gap-2">
            <p className="text-title-1-medium text-text-primary tabular-nums">
              {total.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color="lime">
              +14.8%
            </Chip>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        {STATS.map((stat) => (
          <div
            key={stat.label}
            className="rounded-xl bg-background-primary-default px-3 py-2.5"
          >
            <p className="text-title-3-semibold text-text-primary tabular-nums">
              {stat.value}
            </p>
            <p className="mt-0.5 text-caption-1-medium text-text-tertiary">
              {stat.label}
            </p>
          </div>
        ))}
      </div>

      <div className="flex flex-col gap-2">
        <div className="flex items-center justify-between gap-2">
          <p className="text-body-medium text-text-secondary">活动</p>
          <SegmentedControl
            selectedKeys={[range]}
            onSelectionChange={(keys) => {
              const next = [...keys][0];
              if (next) setRange(String(next) as Range);
            }}
            aria-label="活动范围"
            className="shrink-0"
          >
            <SegmentedControlItem id="weekly">每周</SegmentedControlItem>
            <SegmentedControlItem id="monthly">每月</SegmentedControlItem>
            <SegmentedControlItem id="yearly">每年</SegmentedControlItem>
          </SegmentedControl>
        </div>

        <div className="overflow-x-auto">
          <div className="inline-flex min-w-full flex-col gap-1.5">
            <div
              className="grid gap-[3px]"
              style={{
                gridTemplateColumns: `repeat(53, minmax(0, 1fr))`,
                gridTemplateRows: `repeat(7, 10px)`,
                gridAutoFlow: "column",
              }}
            >
              {cells.map((level, i) => (
                <span
                  key={i}
                  className={cx("size-2.5 rounded-[3px]", LEVEL_CLASS[level])}
                  title={`贡献等级 ${level}`}
                />
              ))}
            </div>
            <div className="flex justify-between px-0.5 text-caption-1-medium text-text-tertiary">
              {MONTHS.filter((_, i) => i % 1 === 0).map((m) => (
                <span key={m}>{m}</span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ComponentType,
  type ReactNode,
} from "react";
import {
  RiBankLine,
  RiCalendarLine,
  RiCloseLine,
  RiCustomerServiceLine,
  RiHomeLine,
  RiKanbanView2,
  RiMegaphoneLine,
  RiSearchLine,
  RiSettings4Line,
  RiSideBarFill,
  RiUserSmileLine,
} from "@remixicon/react";
import { SettingsModal } from "@/components/ui/settings/settings-modal";
import { ThemeToggle } from "@/components/ui/theme/theme-toggle";
import { Badge } from "@/components/ui/badges/badge";
import { CloseButton } from "@/components/ui/buttons/close-button";
import { Kbd } from "@/components/ui/kbd/kbd";
