export function EarningsChartCard({
  className,
  title = "至今已赚到",
}: {
  className?: string;
  /** Headline label when no month is hovered. */
  title?: string;
} = {}) {
  const [period, setPeriod] = useState<Period>("monthly");
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const data = PERIOD_DATA[period];
  const meta = PERIOD_META[period];
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? point.value : meta.total;
  const label = point ? point.label : title;
  const delta = formatDelta(meta.delta);
  const display = useCountUp(Math.round(headlineValue));
  const yMax = useMemo(() => Math.max(...data.map((d) => d.value)) * 1.1, [data]);

  return (
    <section
      className={cx(
        "flex flex-col gap-4 rounded-2xl bg-background-secondary-default p-4",
        className,
      )}
    >
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={`${period}-${activeIndex ?? "total"}`}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              ${formatMoney(display)}
            </p>
            <Chip variant="bold" color={delta.color}>
              {delta.label}
            </Chip>
          </div>
        </div>

        <SegmentedControl
          aria-label="周期"
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const next = [...(keys as Set<string>)][0] as Period | undefined;
            if (next) {
              setPeriod(next);
              setActiveIndex(null);
            }
          }}
          className="shrink-0 self-start"
        >
          <SegmentedControlItem id="weekly">每周</SegmentedControlItem>
          <SegmentedControlItem id="monthly">每月</SegmentedControlItem>
          <SegmentedControlItem id="yearly">每年</SegmentedControlItem>
        </SegmentedControl>
      </div>

      <div className="flex h-[220px] w-full min-w-0 gap-2">
        {/* Optional Y-axis style labels */}
        <div className="flex w-8 shrink-0 flex-col justify-between pb-6 pt-1" aria-hidden>
          {[...Y_TICKS].reverse().map((tick) => (
            <span key={tick} className="text-caption-1-medium text-text-tertiary tabular-nums">
              {tick === 0
                ? "0"
                : yMax >= 1000
                  ? `${Math.round((yMax * tick) / 1000)}k`
                  : Math.round(yMax * tick)}
            </span>
          ))}
        </div>

        <div className="flex min-w-0 flex-1 flex-col">
          <div className="flex min-h-0 flex-1 items-stretch gap-1.5 sm:gap-2">
            {data.map((item, index) => {
              const heightPct = Math.max(4, (item.value / yMax) * 100);
              const active = activeIndex === index;
              return (
                <button
                  key={item.label}
                  type="button"
                  aria-label={`${item.label} $${formatMoney(item.value)}`}
                  className="group relative flex min-w-0 flex-1 cursor-pointer flex-col justify-end outline-none"
                  onMouseEnter={() => setActiveIndex(index)}
                  onMouseLeave={() => setActiveIndex(null)}
                  onFocus={() => setActiveIndex(index)}
                  onBlur={() => setActiveIndex(null)}
                >
                  <div
                    className={cx(
                      "relative flex h-full w-full max-w-6 items-end justify-center self-center overflow-hidden rounded-full bg-chart-track transition-[box-shadow,opacity] duration-150",
                      active ? "ring-1 ring-chart-2-active shadow-xs" : "opacity-90 group-hover:opacity-100",
                    )}
                  >
                    <div
                      className={cx(
                        "w-full rounded-full transition-[height,background-color] duration-300 ease-out",
                        active ? "bg-chart-2-active" : "bg-chart-2",
                      )}
                      style={{ height: `${heightPct}%` }}
                    />
                  </div>
                </button>
              );
            })}
          </div>

          <div className="mt-2 flex gap-1.5 sm:gap-2" aria-hidden>
            {data.map((item) => (
              <span
                key={item.label}
                className="min-w-0 flex-1 text-center text-caption-1-medium text-text-tertiary"
              >
                {item.label}
              </span>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useId, useState } from "react";

import { Chip } from "@/components/ui/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Funnel Chart Card: a horizontal four-stage sign-up funnel drawn as SVG
 * trapezoids with a soft glow. Conversion % pills sit on each stage; the
 * footer lists absolute counts with matching color dots.
 */

export type FunnelStage = {
  label: string;
  value: number;
  /** Share of the funnel top, 0–100. */
  percent: number;
  /** CSS color for the trapezoid fill (chart token). */
  color: string;
  /** Tailwind bg utility for the footer dot. */
  dotClass: string;
};

export const FUNNEL_STAGES: FunnelStage[] = [
  {
    label: "链接已打开",
    value: 197,
    percent: 100,
    color: "var(--color-chart-7-active)",
    dotClass: "bg-chart-7-active",
  },
  {
    label: "开始",
    value: 110,
    percent: 56,
    color: "var(--color-chart-6-active)",
    dotClass: "bg-chart-6-active",
  },
  {
    label: "已完成",
    value: 77,
    percent: 39,
    color: "var(--color-chart-5-active)",
    dotClass: "bg-chart-5-active",
  },
  {
    label: "已转换",
    value: 38,
    percent: 19,
    color: "var(--color-chart-3-active)",
    dotClass: "bg-chart-3-active",
  },
];

const VIEW_W = 400;
const VIEW_H = 140;
const PAD_Y = 8;

function stageBand(percent: number) {
  const h = ((VIEW_H - PAD_Y * 2) * percent) / 100;
  const y0 = (VIEW_H - h) / 2;
  return { y0, y1: y0 + h };
}

function stagePath(index: number, stages: FunnelStage[]) {
  const n = stages.length;
  const w = VIEW_W / n;
  const left = stageBand(stages[index].percent);
  const right = stageBand(stages[Math.min(index + 1, n - 1)].percent);
  const x0 = index * w;
  const x1 = (index + 1) * w;
  // Last stage keeps a slight inward taper so it still reads as a funnel tip.
  const tip = index === n - 1 ? stageBand(Math.max(8, stages[index].percent * 0.72)) : right;
  return `M ${x0} ${left.y0} L ${x1} ${tip.y0} L ${x1} ${tip.y1} L ${x0} ${left.y1} Z`;
}

export function FunnelChartCard({
  stages = FUNNEL_STAGES,
  title = "Sign-up funnel",
  delta = "+5.2%",
  period = "过去 7 天",
  className,
}: {
  stages?: FunnelStage[];
  title?: string;
  delta?: string;
  period?: string;
  className?: string;
} = {}) {
  const glowId = useId();
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const total = stages[0]?.value ?? 0;
  const hovering = activeIndex !== null && activeIndex < stages.length;
  const stage = hovering ? stages[activeIndex] : null;
  const headline = stage?.value ?? total;
  const label = stage?.label ?? title;
  const display = useCountUp(headline);

  return (
    <section
      className={cx(
        "flex h-[344px] min-w-0 flex-1 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={activeIndex ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {display.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color="lime">
              {delta}
            </Chip>
          </div>
        </div>
        <Chip variant="bold" color="soft" className="shrink-0">
          {period}
        </Chip>
      </div>

      <div className="relative min-h-0 w-full flex-1">
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="h-full w-full"
          role="img"
          aria-label={title}
        >
          <defs>
            <filter id={glowId} x="-20%" y="-40%" width="140%" height="180%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="3.5" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {stages.map((s, i) => {
            const dimmed = activeIndex !== null && activeIndex !== i;
            return (
              <path
                key={s.label}
                d={stagePath(i, stages)}
                fill={s.color}
                opacity={dimmed ? 0.28 : 0.92}
                filter={`url(#${glowId})`}
                className="cursor-pointer transition-opacity duration-200 ease"
                onMouseEnter={() => setActiveIndex(i)}
                onMouseLeave={() => setActiveIndex(null)}
              />
            );
          })}
        </svg>

        <div className="pointer-events-none absolute inset-0 grid grid-cols-4">
          {stages.map((s, i) => (
            <div key={s.label} className="flex items-center justify-center">
              <span
                className={cx(
                  "rounded-full bg-background-secondary-default/90 px-2 py-0.5 text-caption-1-medium text-text-primary tabular-nums shadow-card backdrop-blur-sm transition-opacity duration-200 ease",
                  activeIndex !== null && activeIndex !== i && "opacity-40",
                )}
              >
                {s.percent}%
              </span>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-4 gap-2 border-t border-separator-border pt-3">
        {stages.map((s, i) => (
          <button
            key={s.label}
            type="button"
            className={cx(
              "flex min-w-0 flex-col items-start gap-1 rounded-lg px-1 py-0.5 text-start outline-none transition-opacity duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring",
              activeIndex !== null && activeIndex !== i && "opacity-40",
            )}
            onMouseEnter={() => setActiveIndex(i)}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <span className="flex items-center gap-1.5">
              <span className={cx("size-2 shrink-0 rounded-full", s.dotClass)} aria-hidden />
              <span className="truncate text-caption-1-medium text-text-tertiary">{s.label}</span>
            </span>
            <span className="ps-3.5 text-body-medium text-text-primary tabular-nums">
              {s.value.toLocaleString("en-US")}
            </span>
          </button>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";

import { Chip } from "@/components/ui/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Heatmap Chart Card: weekday × hour matrix as a pure CSS grid. Cell tint
 * blends chart-blue into the chart track so the ramp follows the theme;
 * hovering a cell rings it and swaps the headline for that cell's value.
 */

export type HeatmapRow = {
  label: string;
  values: number[];
};

export const HEATMAP_COLUMNS = ["00", "02", "04", "06", "08", "10", "12", "14", "16", "18", "20", "22"];

/** Demo active-user intensity for Mon–Sun × bi-hourly slots. */
export const HEATMAP_ROWS: HeatmapRow[] = [
  { label: "周一", values: [12, 8, 4, 6, 28, 52, 68, 74, 81, 76, 58, 34] },
  { label: "周二", values: [14, 9, 5, 7, 31, 55, 72, 78, 84, 79, 61, 36] },
  { label: "周三", values: [11, 7, 3, 8, 33, 58, 75, 82, 88, 80, 63, 38] },
  { label: "周四", values: [13, 8, 4, 9, 30, 54, 71, 77, 85, 78, 60, 35] },
  { label: "周五", values: [15, 10, 6, 10, 36, 62, 79, 86, 90, 83, 66, 42] },
  { label: "周六", values: [22, 14, 9, 12, 24, 40, 48, 52, 55, 58, 49, 31] },
  { label: "周日", values: [18, 12, 8, 10, 20, 34, 42, 46, 50, 52, 44, 28] },
];

const TIER_CLASSES = [
  "bg-chart-track",
  "bg-chart-6/25",
  "bg-chart-6/45",
  "bg-chart-6/65",
  "bg-chart-6-active/85",
  "bg-chart-6-active",
] as const;

function tierFor(value: number, max: number) {
  if (value <= 0 || max <= 0) return 0;
  const t = value / max;
  if (t < 0.15) return 1;
  if (t < 0.35) return 2;
  if (t < 0.55) return 3;
  if (t < 0.75) return 4;
  return 5;
}

export function HeatmapChartCard({
  rows = HEATMAP_ROWS,
  columns = HEATMAP_COLUMNS,
  title = "Active users",
  headline = 1892,
  delta = "+5.2%",
  period = "过去 7 天",
  className,
}: {
  rows?: HeatmapRow[];
  columns?: string[];
  title?: string;
  headline?: number;
  delta?: string;
  period?: string;
  className?: string;
} = {}) {
  const [hover, setHover] = useState<{ row: number; col: number } | null>(null);

  const max = useMemo(
    () => Math.max(1, ...rows.flatMap((row) => row.values)),
    [rows],
  );

  const cellValue =
    hover && rows[hover.row] ? (rows[hover.row].values[hover.col] ?? 0) : null;
  const label =
    hover && rows[hover.row]
      ? `${rows[hover.row].label} · ${columns[hover.col] ?? ""}:00`
      : title;
  const display = useCountUp(cellValue ?? headline);

  return (
    <section
      className={cx(
        "flex h-[344px] min-w-0 flex-1 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={hover ? `${hover.row}-${hover.col}` : "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {display.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color="lime">
              {delta}
            </Chip>
          </div>
        </div>
        <Chip variant="bold" color="soft" className="shrink-0">
          {period}
        </Chip>
      </div>

      <div className="flex min-h-0 w-full flex-1 flex-col gap-2">
        <div
          className="grid min-h-0 flex-1 gap-1"
          style={{
            gridTemplateColumns: `auto repeat(${columns.length}, minmax(0, 1fr))`,
            gridTemplateRows: `repeat(${rows.length}, minmax(0, 1fr))`,
          }}
        >
          {rows.map((row, ri) => (
            <div key={row.label} className="contents">
              <span className="flex items-center pe-2 text-caption-1-medium text-text-tertiary">
                {row.label}
              </span>
              {row.values.map((value, ci) => {
                const active = hover?.row === ri && hover?.col === ci;
                const dimmed = hover !== null && !active;
                return (
                  <button
                    key={`${row.label}-${columns[ci]}`}
                    type="button"
                    aria-label={`${row.label} ${columns[ci]}:00, ${value}`}
                    className={cx(
                      "min-h-0 min-w-0 rounded-sm outline-none transition-[opacity,box-shadow] duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                      TIER_CLASSES[tierFor(value, max)],
                      active && "ring-2 ring-border-focus-ring ring-offset-1 ring-offset-background-secondary-default",
                      dimmed && "opacity-35",
                    )}
                    onMouseEnter={() => setHover({ row: ri, col: ci })}
                    onMouseLeave={() => setHover(null)}
                    onFocus={() => setHover({ row: ri, col: ci })}
                    onBlur={() => setHover(null)}
                  />
                );
              })}
            </div>
          ))}
        </div>

        <div
          className="grid gap-1"
          style={{ gridTemplateColumns: `auto repeat(${columns.length}, minmax(0, 1fr))` }}
        >
          <span aria-hidden className="pe-2" />
          {columns.map((col) => (
            <span
              key={col}
              className="text-center text-caption-1-medium text-text-tertiary tabular-nums"
            >
              {col}
            </span>
          ))}
        </div>
      </div>

      <div className="flex items-center justify-end gap-2 text-caption-1-medium text-text-tertiary">
        <span>少</span>
        <div className="flex items-center gap-1">
          {TIER_CLASSES.slice(1).map((cls) => (
            <span key={cls} className={cx("size-2.5 rounded-sm", cls)} aria-hidden />
          ))}
        </div>
        <span>更多</span>
      </div>
    </section>
  );
}

