              activeDot={<ActiveDot />}
              isAnimationActive
              animationDuration={450}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";
import { RiArrowLeftSLine, RiArrowRightSLine } from "@remixicon/react";
import { cx } from "@/lib/utils";

type DayMetrics = { move: number; exercise: number; stand: number };

const DEMO_MONTH = 6; // July (0-indexed)
const DEMO_YEAR = 2026;

function metricsForDay(day: number): DayMetrics {
  const move = 40 + ((day * 17) % 60);
  const exercise = 35 + ((day * 13) % 55);
  const stand = 45 + ((day * 11) % 50);
  return { move, exercise, stand };
}

function MiniRings({ m, size = 22 }: { m: DayMetrics; size?: number }) {
  const r = [size * 0.42, size * 0.3, size * 0.18];
  const colors = ["#FF2D55", "#A3E635", "#22D3EE"];
  const values = [m.move, m.exercise, m.stand];
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden>
      {r.map((radius, i) => {
        const c = 2 * Math.PI * radius;
        const pct = Math.min(100, values[i]) / 100;
        return (
          <g key={i}>
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke="var(--color-background-tertiary-default)"
              strokeWidth={size * 0.08}
            />
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={colors[i]}
              strokeWidth={size * 0.08}
              strokeLinecap="round"
              strokeDasharray={c}
              strokeDashoffset={c * (1 - pct)}
              transform={`rotate(-90 ${size / 2} ${size / 2})`}
            />
          </g>
        );
      })}
    </svg>
  );
}

function LargeRings({ m }: { m: DayMetrics }) {
  const size = 168;
  const r = [72, 52, 32];
  const colors = ["#FF2D55", "#A3E635", "#22D3EE"];
  const values = [m.move, m.exercise, m.stand];
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="mx-auto">
      {r.map((radius, i) => {
        const c = 2 * Math.PI * radius;
        const pct = Math.min(100, values[i]) / 100;
        return (
          <g key={i}>
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke="var(--color-background-tertiary-default)"
              strokeWidth={14}
              opacity={0.85}
            />
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={colors[i]}
              strokeWidth={14}
              strokeLinecap="round"
              strokeDasharray={c}
              strokeDashoffset={c * (1 - pct)}
              transform={`rotate(-90 ${size / 2} ${size / 2})`}
              style={{ filter: `drop-shadow(0 0 6px ${colors[i]}66)` }}
            />
          </g>
        );
      })}
    </svg>
  );
}

/**
 * Most Active Days — scrollable month calendar with per-day mini rings and a
 * detail panel for the selected day.
 */
export function MostActiveDaysCard({ className }: { className?: string }) {
  const [selected, setSelected] = useState(10);
  const daysInMonth = 31;
  const startWeekday = new Date(DEMO_YEAR, DEMO_MONTH, 1).getDay(); // 0=Sun
  const selectedMetrics = useMemo(() => metricsForDay(selected), [selected]);

  const cells = useMemo(() => {
    const blanks = Array.from({ length: startWeekday }, () => null);
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
    return [...blanks, ...days];
  }, [startWeekday]);

  return (
    <section
      className={cx(
        "grid w-full min-w-0 gap-3 rounded-2xl bg-background-secondary-default p-3 sm:grid-cols-2 sm:p-4",
        className,
      )}
    >
      <div className="flex flex-col gap-3 rounded-2xl bg-background-primary-default p-3">
        <div className="flex items-start justify-between gap-2">
          <div>
            <p className="text-body-medium text-text-secondary">最活跃的日子</p>
            <p className="mt-0.5 text-title-3-semibold text-text-primary">
              32,459{" "}
              <span className="text-body-medium text-text-tertiary">总步数</span>
            </p>
          </div>
          <div className="inline-flex items-center gap-1 rounded-full border border-border-button-default px-1 py-0.5">
            <button
              type="button"
              aria-label="上一月"
              className="flex size-6 items-center justify-center rounded-full text-foreground-icon-secondary hover:bg-background-secondary-default"
            >
              <RiArrowLeftSLine className="size-4" />
            </button>
            <span className="min-w-10 text-center text-body-2-medium text-text-primary">
              7月
            </span>
            <button
              type="button"
              aria-label="下一月"
              className="flex size-6 items-center justify-center rounded-full text-foreground-icon-secondary hover:bg-background-secondary-default"
            >
              <RiArrowRightSLine className="size-4" />
            </button>
          </div>
        </div>

        <div className="grid grid-cols-7 gap-1 text-center text-caption-1-medium text-text-tertiary">
          {["日", "一", "二", "三", "四", "五", "六"].map((d) => (
            <span key={d}>{d}</span>
          ))}
        </div>

        <div className="grid max-h-[280px] grid-cols-7 gap-1 overflow-y-auto pe-1 [scrollbar-width:thin]">
          {cells.map((day, i) =>
            day === null ? (
              <div key={`b-${i}`} className="h-12" />
            ) : (
              <button
                key={day}
                type="button"
                onClick={() => setSelected(day)}
                className={cx(
                  "flex h-12 flex-col items-center justify-center gap-0.5 rounded-xl outline-none transition-colors",
                  selected === day
                    ? "bg-background-secondary-hover ring-1 ring-border-button-default"
                    : "hover:bg-background-secondary-default",
                )}
              >
                <span className="text-caption-1-medium text-text-secondary">
                  {day}
                </span>
                <MiniRings m={metricsForDay(day)} />
              </button>
            ),
          )}
        </div>
      </div>

      <div className="flex flex-col gap-4 rounded-2xl bg-background-primary-default p-4">
        <p className="text-body-medium text-text-secondary">
          July {selected}, {DEMO_YEAR} 的活动
        </p>
        <div className="flex flex-wrap gap-2">
          <span className="inline-flex items-center gap-1.5 rounded-full bg-status-rose-background px-2.5 py-1 text-body-2-medium text-status-rose-text">
            Move · 816 kcal
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full bg-status-lime-background px-2.5 py-1 text-body-2-medium text-status-lime-text">
            Exercise · 1h 41m
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full bg-status-cyan-background px-2.5 py-1 text-body-2-medium text-status-cyan-text">
            Stand · 5.2 km
          </span>
        </div>
        <LargeRings m={selectedMetrics} />
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { Chip } from "@/components/ui/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Orders Chart Card: a year of monthly orders as bars, this year beside last
 * year for every month, so the comparison is read bar to bar rather than
 * against a line. The header is the same as the revenue chart's: a count-up
 * total with a delta chip, the year-earlier figure under it, and a legend.
 * Hovering a month swaps the headline for that month.
 */

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS_FULL = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

export type OrdersPoint = {
  /** Short month label on the axis. */
  label: string;
  /** Orders this year. */
  current: number;
  /** Orders in the same month a year earlier. */
  previous: number;
};

/** Twelve months that add up to the stat cards' total orders. */
export const ORDERS_DATA: OrdersPoint[] = [
  { label: "Jan", current: 1680, previous: 1510 },
  { label: "Feb", current: 1740, previous: 1480 },
  { label: "Mar", current: 1920, previous: 1650 },
  { label: "Apr", current: 1850, previous: 1620 },
  { label: "May", current: 2040, previous: 1710 },
  { label: "Jun", current: 2110, previous: 1760 },
  { label: "Jul", current: 2290, previous: 1840 },
  { label: "Aug", current: 2180, previous: 1890 },
  { label: "Sep", current: 2320, previous: 1930 },
  { label: "Oct", current: 2410, previous: 1970 },
  { label: "Nov", current: 2280, previous: 1810 },
  { label: "Dec", current: 2342, previous: 1798 },
];

const formatK = (value: number) => (value >= 1000 ? `${(value / 1000).toFixed(value % 1000 === 0 ? 0 : 1)}k` : `${value}`);

function describeDelta(current: number, previous: number) {
  if (previous === 0) return { label: "New", color: "neutral" as const };
  const change = ((current - previous) / previous) * 100;
  const rounded = Math.round(change * 10) / 10;
  if (rounded === 0) return { label: "0%", color: "neutral" as const };
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : ("rose" as const),
  };
}

export function OrdersChartCard({
  data = ORDERS_DATA,
  title = "Orders",
  className,
}: {
  /** Twelve points, one per month; defaults to the demo year. */
  data?: OrdersPoint[];
  /** Headline label when no month is hovered. */
  title?: string;
  className?: string;
} = {}) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const totalCurrent = data.reduce((sum, point) => sum + point.current, 0);
  const totalPrevious = data.reduce((sum, point) => sum + point.previous, 0);
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? point.current : totalCurrent;
  const comparison = point ? point.previous : totalPrevious;
  const delta = describeDelta(headlineValue, comparison);
  const monthIndex = point ? MONTHS.indexOf(point.label) : -1;
  const label = point ? (monthIndex >= 0 ? MONTHS_FULL[monthIndex] : point.label) : title;
  const display = useCountUp(headlineValue);

  const yMax = Math.max(...data.map((d) => Math.max(d.current, d.previous)));

  return (
    <section
      className={cx(
        "flex h-[344px] min-w-0 flex-1 flex-col gap-6 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      {/* Header: label over the count-up figure and its delta; legend on the right */}
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={activeIndex ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {display.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color={delta.color}>
              {delta.label}
            </Chip>
          </div>
          <p className="text-body-2-medium text-text-tertiary tabular-nums">
            {comparison.toLocaleString("en-US")} {point ? "a year earlier" : "last year"}
          </p>
        </div>
        <dl className="flex shrink-0 items-center gap-4 text-body-2-medium text-text-secondary">
          <div className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-chart-9-active" aria-hidden />
            <dt>This year</dt>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-chart-neutral" aria-hidden />
            <dt>Last year</dt>
          </div>
        </dl>
      </div>

      {/* Chart */}
      <div className="min-h-0 w-full flex-1">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={data}
            margin={{ top: 4, right: 6, bottom: 0, left: 0 }}
            barCategoryGap="28%"
            barGap={3}
            onMouseMove={(state) => {
              const index = Number(state?.activeTooltipIndex);
              if (state?.isTooltipActive && Number.isFinite(index)) setActiveIndex(index);
            }}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <YAxis
              width={40}
              domain={[0, yMax * 1.1]}
              tickCount={4}
              tickFormatter={formatK}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <XAxis
              dataKey="label"
              tickLine={false}
              axisLine={false}
              tickMargin={12}
              interval="preserveStartEnd"
              tick={{ fontSize: 13, fill: "var(--color-text-tertiary)" }}
            />
            <Tooltip content={() => null} cursor={{ fill: "var(--color-chart-track)", opacity: 0.5 }} />
            <Bar
              dataKey="previous"
              fill="var(--color-chart-neutral)"
              radius={[4, 4, 0, 0]}
              isAnimationActive
              animationDuration={450}
            />
            <Bar
              dataKey="current"
              fill="var(--color-chart-9-active)"
              radius={[4, 4, 0, 0]}
              isAnimationActive
              animationDuration={450}
            />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}

