  {
    label: "镀铬",
    value: 275,
    fill: "var(--color-chart-2-active)",
    swatchClass: "bg-chart-2-active",
  },
];

export function RadialChartCard({
  data = RADIAL_DATA,
  title = "访客",
  delta = "+5.2%",
  period = "过去 7 天",
  className,
}: {
  data?: RadialItem[];
  title?: string;
  delta?: string;
  period?: string;
  className?: string;
} = {}) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const total = data.reduce((sum, item) => sum + item.value, 0);
  const max = Math.max(...data.map((item) => item.value));
  const hovering = activeIndex !== null && activeIndex < data.length;
  const item = hovering ? data[activeIndex] : null;
  const headline = item?.value ?? total;
  const label = item?.label ?? title;
  const display = useCountUp(headline);

  // Innermost → outermost so larger rings sit outside.
  const chartData = [...data]
    .map((entry, index) => ({
      ...entry,
      // Normalize to the strongest ring so arcs remain readable.
      score: Math.round((entry.value / max) * 100),
      _index: index,
    }))
    .reverse();

  return (
    <section
      className={cx(
        "flex min-h-[380px] min-w-0 flex-1 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={activeIndex ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {display.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color="lime">
              {delta}
            </Chip>
          </div>
        </div>
        <Chip variant="bold" color="soft" className="shrink-0">
          {period}
        </Chip>
      </div>

      <div className="h-[200px] w-full shrink-0">
        <ResponsiveContainer width="100%" height={200}>
          <RadialBarChart
            data={chartData}
            cx="50%"
            cy="50%"
            innerRadius="18%"
            outerRadius="92%"
            startAngle={90}
            endAngle={-270}
            barSize={12}
            onMouseMove={(state) => {
              const payload = (
                state as {
                  activePayload?: Array<{ payload?: { _index?: number } }>;
                }
              )?.activePayload?.[0]?.payload;
              if (payload && typeof payload._index === "number") {
                setActiveIndex(payload._index);
              }
            }}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <PolarAngleAxis type="number" domain={[0, 100]} tick={false} />
            <Tooltip content={() => null} />
            <RadialBar
              dataKey="score"
              background={{ fill: "var(--color-chart-track)" }}
              cornerRadius={6}
              isAnimationActive
              animationDuration={450}
              // Dim non-hovered rings via fill opacity on each cell.
              shape={(props: {
                cx?: number;
                cy?: number;
                innerRadius?: number;
                outerRadius?: number;
                startAngle?: number;
                endAngle?: number;
                fill?: string;
                payload?: { _index?: number };
              }) => {
                const idx = props.payload?._index;
                const dimmed = activeIndex !== null && idx !== activeIndex;
                const {
                  cx = 0,
                  cy = 0,
                  innerRadius = 0,
                  outerRadius = 0,
                  startAngle = 0,
                  endAngle = 0,
                  fill = "currentColor",
                } = props;
                const start = ((startAngle - 90) * Math.PI) / 180;
                const end = ((endAngle - 90) * Math.PI) / 180;
                const x1 = cx + outerRadius * Math.cos(start);
                const y1 = cy + outerRadius * Math.sin(start);
                const x2 = cx + outerRadius * Math.cos(end);
                const y2 = cy + outerRadius * Math.sin(end);
                const x3 = cx + innerRadius * Math.cos(end);
                const y3 = cy + innerRadius * Math.sin(end);
                const x4 = cx + innerRadius * Math.cos(start);
                const y4 = cy + innerRadius * Math.sin(start);
                const large = Math.abs(endAngle - startAngle) > 180 ? 1 : 0;
                const d = [
                  `M ${x1} ${y1}`,
                  `A ${outerRadius} ${outerRadius} 0 ${large} 0 ${x2} ${y2}`,
                  `L ${x3} ${y3}`,
                  `A ${innerRadius} ${innerRadius} 0 ${large} 1 ${x4} ${y4}`,
                  "Z",
                ].join(" ");
                return (
                  <path
                    d={d}
                    fill={fill}
                    opacity={dimmed ? 0.28 : 1}
                    className="transition-opacity duration-150 ease"
                  />
                );
              }}
            />
          </RadialBarChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
        {data.map((entry, i) => (
          <button
            key={entry.label}
            type="button"
            className={cx(
              "flex min-w-0 items-center justify-between gap-2 rounded-2lg bg-background-inner-default px-2.5 py-2 shadow-card outline-none transition-opacity duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring",
              activeIndex !== null && activeIndex !== i && "opacity-40",
              // Last odd tile stretches full width on the final row.
              data.length % 3 === 2 && i === data.length - 1 && "sm:col-span-3",
              data.length % 2 === 1 && i === data.length - 1 && "col-span-2 sm:col-span-1",
              data.length % 3 === 2 && i === data.length - 1 && "sm:col-span-3",
            )}
            onMouseEnter={() => setActiveIndex(i)}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <span className="flex min-w-0 items-center gap-1.5">
              <span className={cx("size-2 shrink-0 rounded-full", entry.swatchClass)} aria-hidden />
              <span className="truncate text-caption-1-medium text-text-tertiary">{entry.label}</span>
            </span>
            <span className="shrink-0 text-body-medium text-text-primary tabular-nums">
              {entry.value.toLocaleString("en-US")}
            </span>
          </button>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useId, useState } from "react";
import {
  Area,
  CartesianGrid,
  ComposedChart,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import { Chip } from "@/components/ui/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Revenue Chart Card: a year of monthly revenue drawn against the year before.
 *
 * The current year is the filled area and solid line, last year the dashed
 * line behind it, so the gap between them is the story. Hovering a month
 * swaps the headline for that month's figure and shows what it was a year
 * earlier. The frame, the count-up headline and the delta chip follow the
 * stat cards and the other chart cards, so it sits in any dashboard row.
 */

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS_FULL = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

export type RevenuePoint = {
  /** Short month label on the axis. */
  label: string;
  /** Revenue this year, in the card's currency. */
  current: number;
  /** Revenue for the same month a year earlier. */
  previous: number;
};

/** Twelve months that add up to the stat cards' total revenue. */
export const REVENUE_DATA: RevenuePoint[] = [
  { label: "Jan", current: 9840, previous: 8210 },
  { label: "Feb", current: 10120, previous: 8460 },
  { label: "Mar", current: 11380, previous: 9950 },
  { label: "Apr", current: 10960, previous: 10240 },
  { label: "May", current: 12210, previous: 10880 },
  { label: "Jun", current: 12740, previous: 11020 },
  { label: "Jul", current: 13980, previous: 11760 },
  { label: "Aug", current: 13120, previous: 12030 },
  { label: "Sep", current: 14210, previous: 12190 },
  { label: "Oct", current: 14690, previous: 12480 },
  { label: "Nov", current: 14360, previous: 12160 },
  { label: "Dec", current: 14703.92, previous: 11924 },
];

const formatK = (value: number) => (value >= 1000 ? `$${Math.round(value / 1000)}k` : `$${value}`);
const formatMoney = (value: number) =>
  value.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 0 });

function describeDelta(current: number, previous: number) {
  if (previous === 0) return { label: "New", color: "neutral" as const };
  const change = ((current - previous) / previous) * 100;
  const rounded = Math.round(change * 10) / 10;
  if (rounded === 0) return { label: "0%", color: "neutral" as const };
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : ("rose" as const),
  };
}

/** The active month's marker on the current-year line. */
function ActiveDot({ cx: x, cy: y }: { cx?: number; cy?: number }) {
  if (x === undefined || y === undefined) return null;
  return (
    <g>
      <circle cx={x} cy={y} r={7} fill="var(--color-chart-2-active)" opacity={0.25} />
      <circle
        cx={x}
        cy={y}
        r={4}
        fill="var(--color-chart-2-active)"
        stroke="var(--color-background-full)"
        strokeWidth={2}
      />
    </g>
  );
}

export function RevenueChartCard({
  data = REVENUE_DATA,
  title = "Revenue",
  className,
}: {
  /** Twelve points, one per month; defaults to the demo year. */
  data?: RevenuePoint[];
  /** Headline label when no month is hovered. */
  title?: string;
  className?: string;
} = {}) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const gradientId = useId();

  const totalCurrent = data.reduce((sum, point) => sum + point.current, 0);
  const totalPrevious = data.reduce((sum, point) => sum + point.previous, 0);
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? point.current : totalCurrent;
  const comparison = point ? point.previous : totalPrevious;
  const delta = describeDelta(headlineValue, comparison);
  const monthIndex = point ? MONTHS.indexOf(point.label) : -1;
  const label = point ? (monthIndex >= 0 ? MONTHS_FULL[monthIndex] : point.label) : title;
  const display = useCountUp(Math.round(headlineValue));

  const yMax = Math.max(...data.map((d) => Math.max(d.current, d.previous)));

  return (
    <section
      className={cx(
        "flex h-[344px] min-w-0 flex-1 flex-col gap-4 overflow-hidden rounded-2xl border border-separator-border bg-background-full px-5 pt-5 pb-4 shadow-xs",
        className,
      )}
    >
      {/* Header: label over the count-up figure and its delta; legend on the right */}
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-caption-1-semibold tracking-[0.04em] text-text-tertiary uppercase">
            {label}
          </p>
          <div className="flex w-full flex-wrap items-center gap-2">
            <p
              key={activeIndex ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              ${formatMoney(display)}
            </p>
            <Chip variant="bold" color={delta.color}>
              {delta.label}
            </Chip>
          </div>
          <p className="text-body-2-medium text-text-tertiary tabular-nums">
            ${formatMoney(comparison)} {point ? "a year earlier" : "last year"}
          </p>
        </div>
        <dl className="flex shrink-0 items-center gap-3 rounded-full bg-background-secondary-default px-3 py-1.5 text-caption-1-medium text-text-secondary">
          <div className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-chart-2-active" aria-hidden />
            <dt>This year</dt>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-chart-neutral" aria-hidden />
            <dt>Last year</dt>
          </div>
        </dl>
      </div>

      {/* Chart */}
      <div className="min-h-0 w-full flex-1">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={data}
            margin={{ top: 8, right: 8, bottom: 0, left: 0 }}
            onMouseMove={(state) => {
              const index = Number(state?.activeTooltipIndex);
              if (state?.isTooltipActive && Number.isFinite(index)) setActiveIndex(index);
            }}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="var(--color-chart-2)" stopOpacity={0.42} />
                <stop offset="55%" stopColor="var(--color-chart-2)" stopOpacity={0.12} />
                <stop offset="100%" stopColor="var(--color-chart-2)" stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid
              vertical={false}
              stroke="var(--color-separator-border)"
              strokeDasharray="3 6"
            />
            <YAxis
              width={40}
              domain={[0, yMax * 1.08]}
              tickCount={4}
              tickFormatter={formatK}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <XAxis
              dataKey="label"
              tickLine={false}
              axisLine={false}
              tickMargin={10}
              interval="preserveStartEnd"
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <Tooltip
              content={() => null}
              cursor={{ stroke: "var(--color-chart-cursor)", strokeWidth: 1, strokeDasharray: "4 4" }}
            />
            <Line
              type="monotone"
              dataKey="previous"
              stroke="var(--color-chart-neutral)"
              strokeWidth={2}
              strokeDasharray="5 5"
              dot={false}
              activeDot={false}
              isAnimationActive
              animationDuration={450}
            />
            <Area
              type="monotone"
              dataKey="current"
              stroke="none"
              fill={`url(#${gradientId})`}
              isAnimationActive
              animationDuration={450}
            />
            <Line
              type="monotone"
              dataKey="current"
              stroke="var(--color-chart-2-active)"
              strokeWidth={2.5}
              dot={false}
              activeDot={<ActiveDot />}
              isAnimationActive
              animationDuration={450}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";

import { Chip } from "@/components/ui/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Sankey Chart Card: tracked-time sources on the left flow into activity
 * targets on the right. Links are approximate cubic ribbons (not a full
 * sankey physics layout) tinted by their target, with hover isolation.
 */

type SankeyNode = {
  id: string;
  label: string;
  value: number;
  color: string;
};

type SankeyLink = {
  source: string;
  target: string;
  value: number;
};

const SOURCES: SankeyNode[] = [
  { id: "focus", label: "焦点", value: 32, color: "var(--color-chart-7-active)" },
  { id: "meeting", label: "会议", value: 18, color: "var(--color-chart-5-active)" },
  { id: "rest", label: "休息", value: 12, color: "var(--color-chart-8-active)" },
  { id: "admin", label: "管理员", value: 14, color: "var(--color-chart-6-active)" },
  { id: "learn", label: "学习", value: 10, color: "var(--color-chart-3-active)" },
];

const TARGETS: SankeyNode[] = [
  { id: "browse", label: "浏览", value: 22, color: "var(--color-chart-7-active)" },
  { id: "write", label: "写作", value: 18, color: "var(--color-chart-5-active)" },
  { id: "message", label: "消息", value: 13, color: "var(--color-chart-4-active)" },
  { id: "prod", label: "生产力", value: 12, color: "var(--color-chart-2-active)" },
  { id: "email", label: "邮箱", value: 8, color: "var(--color-chart-6-active)" },
  { id: "video", label: "视频", value: 14, color: "var(--color-chart-3-active)" },
  { id: "other", label: "其他", value: 13, color: "var(--color-chart-neutral)" },
];

/** Approximate flows that roughly respect source hours and target shares. */
const LINKS: SankeyLink[] = [
  { source: "focus", target: "browse", value: 8 },
  { source: "focus", target: "write", value: 10 },
  { source: "focus", target: "prod", value: 7 },
  { source: "focus", target: "video", value: 4 },
  { source: "focus", target: "other", value: 3 },
  { source: "meeting", target: "message", value: 6 },
  { source: "meeting", target: "email", value: 4 },
  { source: "meeting", target: "browse", value: 4 },
  { source: "meeting", target: "other", value: 4 },
  { source: "rest", target: "video", value: 6 },
  { source: "rest", target: "browse", value: 4 },
  { source: "rest", target: "other", value: 2 },
  { source: "admin", target: "email", value: 3 },
  { source: "admin", target: "message", value: 4 },
  { source: "admin", target: "prod", value: 3 },
  { source: "admin", target: "browse", value: 2 },
  { source: "admin", target: "other", value: 2 },
  { source: "learn", target: "write", value: 4 },
  { source: "learn", target: "browse", value: 3 },
  { source: "learn", target: "video", value: 2 },
  { source: "learn", target: "message", value: 1 },
];

const TRACKED = SOURCES.reduce((sum, node) => sum + node.value, 0);
const SVG_W = 520;
const SVG_H = 220;
const NODE_W = 8;
const LEFT_X = 118;
const RIGHT_X = 400;

function layoutNodes(nodes: SankeyNode[], x: number) {
  const total = nodes.reduce((sum, n) => sum + n.value, 0);
  const gap = 8;
  const usable = SVG_H - gap * (nodes.length - 1);
  let y = 0;
  return nodes.map((node) => {
    const h = (node.value / total) * usable;
    const item = { ...node, x, y, h };
    y += h + gap;
    return item;
  });
}

function ribbonPath(
  x0: number,
  y0: number,
  h0: number,
  x1: number,
  y1: number,
  h1: number,
) {
  const mid = (x0 + x1) / 2;
  const y0b = y0 + h0;
  const y1b = y1 + h1;
  return [
    `M ${x0} ${y0}`,
    `C ${mid} ${y0}, ${mid} ${y1}, ${x1} ${y1}`,
    `L ${x1} ${y1b}`,
    `C ${mid} ${y1b}, ${mid} ${y0b}, ${x0} ${y0b}`,
    "Z",
  ].join(" ");
}

export function SankeyChartCard({
  className,
  axisLabels = ["Tracked time", "Share of tracked time"],
}: {
  className?: string;
  axisLabels?: [string, string];
} = {}) {
  const [hover, setHover] = useState<string | null>(null);
  const display = useCountUp(TRACKED);

  const left = useMemo(() => layoutNodes(SOURCES, LEFT_X), []);
  const right = useMemo(() => layoutNodes(TARGETS, RIGHT_X), []);

  const ribbons = useMemo(() => {
    const sourceCursor = Object.fromEntries(left.map((n) => [n.id, n.y]));
    const targetCursor = Object.fromEntries(right.map((n) => [n.id, n.y]));
    const sourceMap = Object.fromEntries(left.map((n) => [n.id, n]));
    const targetMap = Object.fromEntries(right.map((n) => [n.id, n]));

    return LINKS.map((link, index) => {
      const source = sourceMap[link.source];
      const target = targetMap[link.target];
      if (!source || !target) return null;
      const sourceScale = source.h / source.value;
      const targetScale = target.h / target.value;
      const h0 = link.value * sourceScale;
      const h1 = Math.max(2, (link.value / TRACKED) * 100 * (target.h / target.value));
      const y0 = sourceCursor[link.source];
      const y1 = targetCursor[link.target];
      sourceCursor[link.source] += h0;
      targetCursor[link.target] += Math.min(h1, target.h * 0.35);
      return {
        key: `${link.source}-${link.target}-${index}`,
        sourceId: link.source,
        targetId: link.target,
        color: target.color,
        d: ribbonPath(source.x + NODE_W, y0, h0, target.x, y1, Math.min(h1, 14)),
      };
    }).filter(Boolean) as {
      key: string;
      sourceId: string;
      targetId: string;
      color: string;
      d: string;
    }[];
  }, [left, right]);

  const dimmed = (id: string) => hover !== null && hover !== id;

  return (
    <section
      className={cx(
        "flex min-h-[360px] min-w-0 flex-1 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="text-body-medium text-text-secondary">Tracked time</p>
          <div className="flex items-center gap-2">
            <p className="animate-number-fade text-title-1-medium text-text-primary tabular-nums">
              {display}h
            </p>
            <Chip variant="bold" color="soft">
              本周
            </Chip>
          </div>
        </div>
      </div>

      <div className="relative min-h-0 w-full flex-1">
        <svg
          viewBox={`0 0 ${SVG_W} ${SVG_H}`}
          className="h-full w-full overflow-visible"
          role="img"
          aria-label="Tracked time sankey"
        >
          {ribbons.map((ribbon) => {
            const active =
              hover === null ||
              hover === ribbon.sourceId ||
              hover === ribbon.targetId;
            return (
              <path
                key={ribbon.key}
                d={ribbon.d}
                fill={ribbon.color}
                opacity={active ? 0.35 : 0.06}
                className="transition-opacity duration-200"
                onMouseEnter={() => setHover(ribbon.sourceId)}
                onMouseLeave={() => setHover(null)}
              />
            );
          })}

          {left.map((node) => (
            <g
              key={node.id}
              onMouseEnter={() => setHover(node.id)}
              onMouseLeave={() => setHover(null)}
              className="cursor-default"
              opacity={dimmed(node.id) ? 0.25 : 1}
            >
              <rect
                x={node.x}
                y={node.y}
                width={NODE_W}
                height={node.h}
                rx={4}
                fill={node.color}
              />
              <text
                x={node.x - 10}
                y={node.y + node.h / 2}
                textAnchor="end"
                dominantBaseline="middle"
                className="fill-text-secondary"
                style={{ fontSize: 12, fontWeight: 500 }}
              >
                {node.label}
                <tspan className="fill-text-tertiary" dx={4}>
                  {node.value}h
                </tspan>
              </text>
            </g>
          ))}

          {right.map((node) => (
            <g
              key={node.id}
              onMouseEnter={() => setHover(node.id)}
              onMouseLeave={() => setHover(null)}
              className="cursor-default"
              opacity={dimmed(node.id) ? 0.25 : 1}
            >
              <rect
                x={node.x}
                y={node.y}
                width={NODE_W}
                height={node.h}
                rx={4}
                fill={node.color}
              />
              <text
                x={node.x + NODE_W + 10}
                y={node.y + node.h / 2}
                dominantBaseline="middle"
                className="fill-text-secondary"
                style={{ fontSize: 12, fontWeight: 500 }}
              >
                {node.label}
                <tspan className="fill-text-tertiary" dx={4}>
                  {node.value}%
