export type ScatterPoint = {
  x: number;
  y: number;
  z: number;
  label?: string;
};

export type ScatterSeries = {
  label: string;
  color: string;
  swatchClass: string;
  points: ScatterPoint[];
};

export const SCATTER_SERIES: ScatterSeries[] = [
  {
