  emerald: "from-emerald-500 to-emerald-600",
};

const DELTA_STYLES: Record<
  NonNullable<Stat["deltaColor"]>,
  { icon: IconComponent; className: string; pill: string }
> = {
  lime: {
    icon: RiArrowUpCircleFill,
    className: "text-status-lime-text",
    pill: "bg-status-lime-background",
  },
  rose: {
    icon: RiArrowDownCircleFill,
    className: "text-status-rose-text",
    pill: "bg-status-rose-background",
  },
  neutral: {
    icon: RiIndeterminateCircleFill,
    className: "text-text-secondary",
    pill: "bg-background-secondary-default",
  },
};

/** Tinted pill with a direction glyph — the footer band's delta readout, in
 *  the same lime and rose the chart cards use for their trend chips. */
function DeltaPill({
  delta,
  deltaColor = "neutral",
}: {
  delta: string;
  deltaColor?: NonNullable<Stat["deltaColor"]>;
}) {
  const localize = useTemplateCopy();
  const { icon: Icon, className, pill } = DELTA_STYLES[deltaColor];
  return localize((
    <span
      className={cx(
        "flex shrink-0 items-center gap-1 rounded-full py-0.5 pe-2 ps-1",
        pill,
      )}
    >
      <Icon className={cx("size-4 shrink-0", className)} aria-hidden />
      <span className={cx("text-body-medium whitespace-nowrap tabular-nums", className)}>
        {delta}
      </span>
    </span>
  ));
}

/** Bare info glyph with a tooltip — the footer header's trailing control.
 *  Opens on hover and focus as tooltips do, and on click as well, since a
 *  glyph this small reads as a button and gets tapped. */
function StatHint({ label, hint }: { label: string; hint: string }) {
  const localize = useTemplateCopy();
  const [open, setOpen] = useState(false);
  return localize((
    <TooltipTrigger delay={200} isOpen={open} onOpenChange={setOpen}>
      <Focusable>
        <button
          type="button"
          aria-label={`About ${label}`}
          onClick={() => setOpen((isOpen) => !isOpen)}
          className="flex shrink-0 cursor-pointer items-center justify-center rounded-full text-foreground-icon-secondary outline-none transition-colors duration-150 ease hover:text-foreground-icon-primary focus-visible:ring-2 focus-visible:ring-border-focus-ring"
        >
          <RiInformationFill className="size-5" aria-hidden />
        </button>
      </Focusable>
      <Tooltip size="md">{hint}</Tooltip>
    </TooltipTrigger>
  ));
}

function PlainStatCard({ stat }: { stat: Stat }) {
  const localize = useTemplateCopy();
  const resolved = resolveStat(stat);
  const Icon = resolved.icon;
  return localize((
    <section className="flex h-[132px] min-w-0 flex-col items-start justify-between rounded-2xl bg-background-secondary-default p-4">
      <span className="flex items-center rounded-md bg-stat-card-icon-background p-1.5">
        <Icon className="size-5 shrink-0 text-foreground-icon-primary" aria-hidden />
      </span>
      <div className="flex w-full flex-col gap-0.5">
        <p className="w-full text-body-medium text-text-secondary">{resolved.label}</p>
        <div className="flex w-full flex-wrap items-center gap-2">
          <p className="text-title-1-medium whitespace-nowrap text-text-primary">{resolved.value}</p>
          <Chip variant="bold" color={resolved.deltaColor}>
            {resolved.delta}
          </Chip>
        </div>
      </div>
    </section>
  ));
}

function FooterStatCard({ stat }: { stat: Stat }) {
  const localize = useTemplateCopy();
  const resolved = resolveStat(stat);
  const Icon = resolved.icon;
  return localize((
    <section className="flex min-w-0 flex-col rounded-2xl bg-background-secondary-default p-2">
      {/* Icon tile + optional info glyph, both hanging from the same top inset */}
      <div className="flex w-full items-start justify-between gap-2.5 p-2">
        <span
          className={cx(
            "flex size-10 shrink-0 items-center justify-center rounded-2lg bg-linear-to-b",
            TILE_TONES[resolved.tone ?? "blue"],
          )}
        >
          <Icon className="size-5 shrink-0 text-white" aria-hidden />
        </span>
        {resolved.hint && <StatHint label={resolved.label} hint={resolved.hint} />}
      </div>

      {/* Label sits directly over the number, as on the plain cards */}
      <div className="flex flex-col gap-0.5 px-2 pt-2.5 pb-3.5">
        <p className="truncate text-body-medium text-text-secondary">{resolved.label}</p>
        <p className="text-display-4-medium whitespace-nowrap text-text-primary tabular-nums">
          {resolved.value}
        </p>
      </div>

      {/* Footer band: comparison caption + delta pill on an inner tile */}
      <div className="mt-auto flex w-full items-center justify-between gap-2 rounded-2lg bg-background-inner-default py-1.5 pe-1.5 ps-2.5 shadow-card">
        <p className="truncate text-body-regular text-text-secondary">
          {resolved.caption ?? "From last month"}
        </p>
        <DeltaPill delta={resolved.delta} deltaColor={resolved.deltaColor} />
      </div>
    </section>
  ));
}

export function StatCards({
  variant = "plain",
  stats,
  count,
  columns = 4,
  className,
}: {
  variant?: StatCardsVariant;
  /** KPI cards to render; defaults to demo metrics matching the variant. */
  stats?: Stat[];
  /** How many KPI cards to render (from the start of the list). */
  count?: number;
  /** Columns at the widest breakpoint - 2 keeps the grid two-up for
   *  narrower hosts (docs previews, split layouts), 1 pins a single
   *  column at every width. */
  columns?: 1 | 2 | 4;
  className?: string;
} = {}) {
  const localize = useTemplateCopy();
  const items =
    stats ?? (variant === "footer" ? DEFAULT_FOOTER_STATS : DEFAULT_STATS);
  return localize((
    <div
      className={cx(
        "grid w-full gap-4",
        // The footer cards carry a display-size value, so they go one per
        // row on phones where the plain cards still fit two up.
        columns === 1
          ? "grid-cols-1"
          : variant === "footer"
            ? "grid-cols-1 sm:grid-cols-2"
            : "grid-cols-2",
        // Prefer host-width when available; fall back to viewport breakpoints
        // so narrow docs layouts don't force a crushed 4-up row.
        columns === 4 &&
          (variant === "footer"
            ? "@container @min-[820px]:grid-cols-4 xl:grid-cols-4"
            : "@container @min-[640px]:grid-cols-4 lg:grid-cols-4"),
        className,
      )}
    >
      {items.slice(0, count ?? items.length).map((stat) =>
        variant === "footer" ? (
          <FooterStatCard key={stat.label} stat={stat} />
        ) : (
          <PlainStatCard key={stat.label} stat={stat} />
        ),
      )}
    </div>
  ));
}

"use client";

import { useState } from "react";

import { WeekRangePill } from "@/components/ui/medical/week-range-pill";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Steps Card: weekly step totals as teal bars in gray tracks (earnings-style),
 * with a week-range switcher and a count-up headline.
 */

type DayPoint = { label: string; value: number };

const WEEKS: { label: string; total: number; days: DayPoint[] }[] = [
  {
    label: "6/29 - 7/5",
    total: 31600,
    days: [
      { label: "周一", value: 4200 },
      { label: "周二", value: 5100 },
      { label: "周三", value: 3800 },
      { label: "周四", value: 5600 },
      { label: "周五", value: 4900 },
      { label: "周六", value: 6200 },
      { label: "周日", value: 1800 },
    ],
  },
  {
    label: "6/22 - 6/28",
    total: 28420,
    days: [
      { label: "周一", value: 3600 },
      { label: "周二", value: 4400 },
      { label: "周三", value: 4100 },
      { label: "周四", value: 3900 },
      { label: "周五", value: 5200 },
      { label: "周六", value: 4700 },
      { label: "周日", value: 2520 },
    ],
  },
  {
    label: "7/6 - 7/12",
    total: 33840,
    days: [
      { label: "周一", value: 4800 },
      { label: "周二", value: 5300 },
      { label: "周三", value: 4500 },
      { label: "周四", value: 5100 },
      { label: "周五", value: 4700 },
      { label: "周六", value: 5900 },
      { label: "周日", value: 3540 },
    ],
  },
];

export function StepsCard({ className }: { className?: string } = {}) {
  const [weekIndex, setWeekIndex] = useState(0);
  const [hover, setHover] = useState<number | null>(null);
  const week = WEEKS[weekIndex];
  const display = useCountUp(week.total);
  const max = Math.max(...week.days.map((d) => d.value));

  return (
    <section
      className={cx(
        "flex h-[320px] min-w-0 flex-1 flex-col gap-5 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="text-body-medium text-text-secondary">步数</p>
          <p
            key={week.label}
            className="animate-number-fade text-title-1-medium text-text-primary tabular-nums"
          >
            {display.toLocaleString("en-US")}
          </p>
          <p className="text-body-2-medium text-text-tertiary">总步数</p>
        </div>
        <WeekRangePill
          label={week.label}
          onPrev={() => setWeekIndex((i) => (i + WEEKS.length - 1) % WEEKS.length)}
          onNext={() => setWeekIndex((i) => (i + 1) % WEEKS.length)}
        />
      </div>

      <div className="flex min-h-0 flex-1 items-end gap-2.5 px-1 pb-1">
        {week.days.map((day, index) => {
          const height = `${Math.max(8, (day.value / max) * 100)}%`;
          const active = hover === index;
          return (
            <button
              key={`${week.label}-${day.label}`}
              type="button"
              className="group flex h-full min-w-0 flex-1 flex-col items-center gap-2 outline-none"
              onMouseEnter={() => setHover(index)}
              onMouseLeave={() => setHover(null)}
              aria-label={`${day.label} ${day.value.toLocaleString("en-US")} 步`}
            >
              <div
                className={cx(
                  "relative flex w-full flex-1 items-end justify-center rounded-xl bg-chart-track/80 px-1.5 py-1.5 transition-shadow duration-150",
                  active && "ring-1 ring-chart-cursor shadow-xs",
                )}
              >
                <div
                  className="w-full origin-bottom rounded-lg bg-chart-1-active animate-bar-rise"
                  style={{
                    height,
                    animationDelay: `${index * 45}ms`,
                  }}
                />
              </div>
              <span className="text-caption-1-medium text-text-tertiary">{day.label}</span>
            </button>
          );
        })}
      </div>
    </section>
  );
}
